	_cleanup_g_free_ char *name = NULL;
	off_t ppos;
	ssize_t retval;
	int fhandle;

	ppos = a % TREEPAGESIZE;
	if(len > (size_t)(TREEPAGESIZE - ppos))
		len = TREEPAGESIZE - ppos;

	name = g_strdup(client->exportname);
	fhandle = open_treefile(name, O_RDONLY, client->exportsize, a, NULL);
	if(fhandle < 0) {
		if(errno == ENOENT) {
			/* the block was never written, so it reads as
			 * zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}

	DEBUG("(READ from treefile offset %llu len %u), ",
