	retval = pread(fhandle, buf, len, ppos);
	if(retval >= 0 && (size_t)retval < len) {
		/* the tail of a block file that was never written
		 * reads as zeroes */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}
	close(fhandle);
	return retval;
}

