/*
 * Tree files support.
 *
 * An export using the treefiles option is stored as a tree of small
 * block files rather than as one large file. The export data is split
 * into TREEPAGESIZE-byte blocks; every block lives in its own file.
 * The block files are spread over a tree of directories such that no
 * directory ever holds more than TREEDIRSIZE files or subdirectories.
 * This allows exporting large virtual block devices on filesystems
 * that do not handle large files well (fuse/ftpfs, davfs and other
 * network filesystems).
 *
 * Block n of the export is stored as
 * <exportname>/TREE<xxxx>/.../TREE<xxxx>/FILE<xxxx>, where the xxxx
 * numbers are the digits of n in base TREEDIRSIZE; the least
 * significant digit determines the file name, and every further digit
 * determines one directory level, the outermost directory first.
 */

#include "lfs.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "nbd-debug.h"
#include "treefiles.h"

/* enough digits to address any export that fits in an off_t */
#define TREE_MAX_DEPTH 8

/* length of one "/TREExxxx" or "/FILExxxx" path component, including
 * the trailing NUL */
#define TREE_COMPONENT_LEN 10

/* Mutex serializing modifications of the tree (creation of block
 * files and their parent directories) */
pthread_mutex_t treefiles_mutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Number of directory levels below the base directory needed to store
 * an export of the given size.
 *
 * @param size the total size of the export
 * @return the number of TREE directory levels, at least 1
 **/
static int tree_depth(off_t size) {
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t capacity = TREEDIRSIZE;
	int depth = 0;

	while(capacity < blocks) {
		capacity *= TREEDIRSIZE;
		depth++;
	}
	assert(depth < TREE_MAX_DEPTH);
	if(depth < 1) {
		depth = 1;
	}
	return depth;
}

int tree_path_extra(off_t size) {
	return (tree_depth(size) + 1) * TREE_COMPONENT_LEN + 1;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export.
 *
 * @param name on input the base directory of the export (i.e., the
 * export name); on output the full path of the block file. The
 * buffer must be at least strlen(name) + tree_path_extra(size)
 * bytes long
 * @param lenmax the size of the name buffer
 * @param size the total size of the export
 * @param pos the offset into the export
 * @param ppos [out] the offset into the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int digits[TREE_MAX_DEPTH];
	off_t block;
	int depth;
	int len;
	int i;

	*ppos = pos % TREEPAGESIZE;
	if(pos < 0 || pos >= size) {
		return;
	}
	block = pos / TREEPAGESIZE;
	depth = tree_depth(size);
	for(i = 0; i <= depth; i++) {
		digits[i] = block % TREEDIRSIZE;
		block /= TREEDIRSIZE;
	}
	len = strlen(name);
	for(i = depth; i >= 1 && len < lenmax; i--) {
		len += snprintf(name + len, lenmax - len, "/TREE%04d",
				digits[i]);
	}
	if(len < lenmax) {
		snprintf(name + len, lenmax - len, "/FILE%04d", digits[0]);
	}
}

/**
 * Create all directories leading up to the file named by path, like
 * mkdir -p does. Existing directories are left alone.
 *
 * @param path the full path of a file; all directory components of
 * the path are created. The buffer is temporarily modified.
 **/
void mkdir_path(char *path) {
	char *p;

	for(p = path + 1; *p != '\0'; p++) {
		if(*p == '/') {
			*p = '\0';
			if(mkdir(path, 0700) < 0 && errno != EEXIST) {
				DEBUG("could not create directory %s: %s",
				      path, strerror(errno));
			}
			*p = '/';
		}
	}
}

/**
 * Open the block file holding the data at a given offset of a
 * treefiles export, creating it (and any missing directories) if
 * asked to.
 *
 * @param name the base directory of the export (i.e., the export
 * name)
 * @param mode the open(2) flags; the file is only created if O_CREAT
 * is set
 * @param size the total size of the export
 * @param pos the offset into the export
 * @param mutex if not NULL, a mutex to serialize tree modifications
 * @return a file descriptor on success, -1 on failure
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char *path;
	off_t ppos;
	int pathlen;
	int fd;

	pathlen = strlen(name) + tree_path_extra(size);
	path = malloc(pathlen);
	if(path == NULL) {
		return -1;
	}
	strcpy(path, name);
	construct_path(path, pathlen, size, pos, &ppos);
	if(mutex != NULL) {
		pthread_mutex_lock(mutex);
	}
	if(mode & O_CREAT) {
		mkdir_path(path);
	}
	fd = open(path, mode, 0600);
	if(fd < 0 && errno == ENOENT && (mode & O_CREAT)) {
		/* a concurrent TRIM may have removed the file; retry
		 * once, recreating any missing directories */
		mkdir_path(path);
		fd = open(path, mode, 0600);
	}
	if(mutex != NULL) {
		pthread_mutex_unlock(mutex);
	}
	free(path);
	return fd;
}

/**
 * Delete the block file holding the data at a given offset of a
 * treefiles export. Not existing files are silently ignored.
 *
 * @param name the base directory of the export (i.e., the export
 * name)
 * @param size the total size of the export
 * @param pos the offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char *path;
	off_t ppos;
	int pathlen;

	pathlen = strlen(name) + tree_path_extra(size);
	path = malloc(pathlen);
	if(path == NULL) {
		return;
	}
	strcpy(path, name);
	construct_path(path, pathlen, size, pos, &ppos);
	if(unlink(path) < 0 && errno != ENOENT) {
		DEBUG("could not delete treefile %s: %s",
		      path, strerror(errno));
	}
	free(path);
}

/**
 * Zero out part of the block file holding the data at a given offset
 * of a treefiles export. If the block file does not exist, there is
 * nothing to do, as the block reads as zeroes then anyway.
 *
 * @param name the base directory of the export (i.e., the export
 * name)
 * @param size the total size of the export
 * @param from the offset into the export where zeroing should start
 * @param len the number of bytes to zero
 **/
static void zero_treefile(char *name, off_t size, off_t from, off_t len) {
	static const char zeroes[TREEPAGESIZE];
	char *path;
	off_t ppos;
	int pathlen;
	int fd;

	pathlen = strlen(name) + tree_path_extra(size);
	path = malloc(pathlen);
	if(path == NULL) {
		return;
	}
	strcpy(path, name);
	construct_path(path, pathlen, size, from, &ppos);
	fd = open(path, O_RDWR);
	if(fd < 0) {
		free(path);
		return;
	}
	if(pwrite(fd, zeroes, len, ppos) < 0) {
		DEBUG("could not zero treefile %s: %s",
		      path, strerror(errno));
	}
	close(fd);
	free(path);
}

/**
 * Handle a TRIM request on a treefiles export. Block files that are
 * covered completely by the trimmed range are deleted, so that the
 * corresponding blocks read as zeroes again; partially covered block
 * files are zeroed out for the trimmed part.
 *
 * @param name the base directory of the export (i.e., the export
 * name)
 * @param size the total size of the export
 * @param from the offset into the export where the trim starts
 * @param len the number of bytes to trim
 **/
void trim_treefiles(char *name, off_t size, off_t from, off_t len) {
	off_t end = from + len;
	off_t page;

	for(page = (from / TREEPAGESIZE) * TREEPAGESIZE;
	    page < end;
	    page += TREEPAGESIZE) {
		off_t blockend = page + TREEPAGESIZE;
		off_t start;
		off_t stop;

		if(blockend > size) {
			blockend = size;
		}
		start = from > page ? from : page;
		stop = end < blockend ? end : blockend;
		if(start == page && stop == blockend) {
			delete_treefile(name, size, page);
		} else {
			zero_treefile(name, size, start, stop - start);
		}
	}
}

